const assert = require('node:assert/strict');
const fs = require('node:fs');
const path = require('node:path');
const root = path.resolve(__dirname, '..');
const drawing = fs.readFileSync(path.join(root, 'js/prototype-drawing.js'), 'utf8');
const ui = fs.readFileSync(path.join(root, 'js/prototype-project-ui.js'), 'utf8');
new Function(drawing);
new Function(ui);
for (const [button, kind, generate] of [['dxf', 'dxf', 'dxf(live)'], ['pdf', 'pdf', 'pdf(live,root.document)']]) {
  const start = drawing.indexOf(`host.querySelector('[data-drawing-${button}]')`);
  assert(start >= 0, `${button} button listener exists`);
  const end = drawing.indexOf('\n', start);
  const listener = drawing.slice(start, end);
  assert(listener.includes(generate), `${button} bytes are generated by the existing drawing function`);
  assert(listener.indexOf(generate) < listener.indexOf('saveAndDownload'), `${button} generation completes before archival starts`);
  assert(listener.includes(`kind:'${kind}'`), `${button} archives under its actual file type`);
  assert(!listener.includes('download('), `${button} cannot bypass the archive before download`);
}
const archiveStart = ui.indexOf('window.AHUPrototypeDrawingArchive = {');
const archiveEnd = ui.indexOf('\n  };', archiveStart);
assert(archiveStart >= 0 && archiveEnd > archiveStart, 'the UI exposes a drawing archive hook');
const archive = ui.slice(archiveStart, archiveEnd);
assert(archive.includes("state.source !== 'shared'"), 'only committed shared projects can be formally exported');
assert(archive.includes('if (isDirty())'), 'unsaved project changes are detected before archival');
assert(archive.includes('persistActiveUnit();') && archive.includes('store.save(projects)'), 'dirty confirmed project data is saved before drawing archival');
assert(archive.indexOf('store.save(projects)') < archive.indexOf('buildArtifact()'), 'drawing bytes are regenerated after the save updates the effective revision');
assert(drawing.includes('buildArtifact:()=>{const fresh=current();return{filename:fresh.unit.no'), 'PDF/DXF filename and bytes use the newly saved equipment number');
assert(archive.indexOf('store.lifecycle.export') < archive.indexOf('anchor.click()'), 'the file download follows successful snapshot archival');
assert(archive.includes('syncFrozenExport(project, result)'), 'successful export synchronizes the frozen snapshot into the active workbench');
console.log('通过：PDF/DXF 先生成实际文件、成功归档同版快照后才允许下载。');
